  function bulkEnergize(output, energy, input, amount) {
    if (!amount) amount = 1
    let id = output.getId().split(":")[1]
    let loop = 0
    let ingredients = []
    while (loop <= 5) {
      for (let item = 1; item <= amount; item++) {
        ingredients.push(input)
      }
      allthemods.recipes.powah
        .energizing(Item.of(output.item, (loop + amount) / amount), energy * (ingredients.length / amount), ingredients)
        .id(`allthemods:powah/energizing/${id}_${(loop + amount) / amount}`)
      loop = loop + amount
    }
  }

