// Auto-claim 7x7 chunks for player island on creation
// Authored for Onter's inn ATM 10 Skyblock

ServerEvents.command("skyblock", (event) => {
  let player = event.player
  if (!player) return

  let input = event.input.toLowerCase()
  if (input.includes("create") || input.includes("join") || input.includes("home")) {
    // Schedule claim execution after player teleport to new island
    event.server.scheduleInTicks(30, (callback) => {
      if (!player || !player.isAlive()) return

      let username = player.username
      // Claim 7x7 chunks (radius ~48 blocks around player position)
      event.server.runCommandSilent(
        `execute at ${username} run ftbchunks admin claim_as ${username} 48`
      )

      player.tell(
        Text.of("§6[Onter's inn] §aТерритория вашего острова (7x7 чанков) успешно запривачена!")
      )
    })
  }
})
